enum Flag: String, CaseIterable {
    case newCheckout, videoAutoplay
    var defaultValue: Bool { false }          // safe if remote config fails
}

protocol FlagProvider: Sendable { func isEnabled(_ flag: Flag) -> Bool }

struct RemoteFlags: FlagProvider {
    let snapshot: [String: Bool]              // fetched, cached on disk
    func isEnabled(_ flag: Flag) -> Bool { snapshot[flag.rawValue] ?? flag.defaultValue }
}
